/**
 * Printables (Enhancement 4). Data only: the PDFs are generated by scripts/make-printables.mjs and
 * served from public/printables/. Free for everyone, no sign-in, no payment.
 *
 * Paid packs later: set `isPaid: true` on a pack. Paid packs are hidden everywhere until a purchase
 * flow exists (none is built). No price, paywall or purchase step appears in the app.
 */
export interface PrintablePack {
  id: string;
  title: string;
  isPaid: boolean;
}

export interface Printable {
  /** Also the URL: /printables/<id> */
  id: string;
  packId: string;
  title: string;
  description: string;
  art: string;
  /** PDF paths. Black and white is offered where it prints better at home. */
  files: { colour: string; bw?: string };
  preview: string;
  pageSize: "A4" | "Letter";
  orientation: "portrait" | "landscape";
  /** Contains Arabic, a dua or a verse: needs the same review as the rest of the content. */
  containsReligiousText: boolean;
  reviewStatus: "pendingReview" | "approved";
  /** Not ready to publish. Never listed. */
  isPlaceholder?: boolean;
  sortOrder: number;
}

