/** What anyone may see and download: free packs, not placeholders. */
export function listedPrintables(all: Printable[] = PRINTABLES, packs: PrintablePack[] = PACKS): Printable[] {
  const free = new Set(packs.filter((p) => !p.isPaid).map((p) => p.id));
  return all.filter((p) => !p.isPlaceholder && free.has(p.packId) && p.files.colour).sort((a, b) => a.sortOrder - b.sortOrder);
}

export function findPrintable(id: string | undefined): Printable | undefined {
  return listedPrintables().find((p) => p.id === id);
}
